-- stock-ledger-seed.sql
-- 30 days of synthetic stock ledger history for StockLedgerIT.
-- Uses fixed UUID prefix dd000000 to avoid collision with other seed fixtures.

-- Re-use the cc000000 part/location from stock-movement-seed.sql
-- or define self-contained rows if stock-movement-seed is not loaded.

INSERT INTO part (id, part_number, name, unit_of_measure, reorder_point, reorder_quantity, active)
VALUES
    ('dd000000-0000-0000-0001-000000000001', 'LDGR-P1', 'Ledger Part Alpha', 'EACH', 5, 10, TRUE),
    ('dd000000-0000-0000-0001-000000000002', 'LDGR-P2', 'Ledger Part Beta',  'EACH', 5, 10, TRUE)
ON CONFLICT (id) DO NOTHING;

INSERT INTO stock_location (id, name, location_type)
VALUES
    ('dd000000-0000-0000-0002-000000000001', 'Ledger Warehouse', 'WAREHOUSE')
ON CONFLICT (id) DO NOTHING;

-- Balance starts at 100 units for LDGR-P1 (matches initial ledger entries below)
INSERT INTO stock_balance (id, part_id, location_id, quantity_on_hand, quantity_reserved, version)
VALUES
    ('dd000000-0000-0000-0003-000000000001',
     'dd000000-0000-0000-0001-000000000001',
     'dd000000-0000-0000-0002-000000000001', 70, 0, 0),
    ('dd000000-0000-0000-0003-000000000002',
     'dd000000-0000-0000-0001-000000000002',
     'dd000000-0000-0000-0002-000000000001', 50, 0, 0)
ON CONFLICT (id) DO NOTHING;

